import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize row-wise column permutations for serialized character-Trie reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Initialize the optimizer and retain the optional source dataframe."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert one cell to the evaluator's missing-as-empty serialization."""
        try:
            missing = pd.isna(value)
            if bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact common-prefix length using bounded binary search."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0
        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested column groups contiguous without dropping any column."""
        if not col_merge:
            return list(order)

        position = {c: i for i, c in enumerate(order)}
        groups = {}
        claimed = set()

        for requested in col_merge:
            group = [c for c in order if c in requested and c not in claimed]
            if not group:
                continue
            group.sort(key=position.__getitem__)
            for c in group:
                groups[c] = group
                claimed.add(c)

        result = []
        emitted = set()
        for c in order:
            if c in emitted:
                continue
            group = groups.get(c)
            if group is None:
                result.append(c)
                emitted.add(c)
            else:
                result.extend(group)
                emitted.update(group)
        return result

    @staticmethod
    def _strings(text, orders):
        """Serialize every row according to its supplied source-column order."""
        return [
            "".join(text[r][j] for j in orders[r])
            for r in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Create frequency-ranked global orders using pair-repetition mass."""
        n = len(text)
        m = len(columns)
        stats = []

        for j in range(m):
            counts = Counter(text[r][j] for r in range(n))
            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat_mass = sum(
                len(value) * (count - 1)
                for value, count in counts.items()
            )
            stats.append((pair_mass, repeat_mass, len(counts)))

        rankings = [
            sorted(
                range(m),
                key=lambda j: (-stats[j][0], -stats[j][1], stats[j][2], j),
            ),
            sorted(
                range(m),
                key=lambda j: (-stats[j][1], -stats[j][0], stats[j][2], j),
            ),
        ]

        lookup = {column: j for j, column in enumerate(columns)}
        candidates = []
        for ranking in rankings:
            names = self._merge(
                columns, [columns[j] for j in ranking], []
            )
            candidates.append([lookup[name] for name in names])

        # Apply merges after ranking, while retaining the original source indexes.
        if col_merge:
            candidates = []
            for ranking in rankings:
                names = self._merge(
                    columns, [columns[j] for j in ranking], col_merge
                )
                candidates.append([lookup[name] for name in names])

        return candidates, rankings[0], stats

    def _prototype_alignment(self, text, columns, col_merge, global_order):
        """
        Build a bounded multi-anchor prefix-packing candidate.

        Up to four far-apart anchor rows are selected under the global order.
        Rows are assigned to anchors by actual character-prefix agreement, then
        each row greedily chooses fields that best continue its assigned anchor
        string. Two assignment/construction rounds are performed.
        """
        n = len(text)
        m = len(columns)

        if n == 0 or m == 0:
            return [[] for _ in range(n)]

        # The strategy is deliberately bounded for wide or large inputs.
        scan_rows = list(range(min(n, 256)))
        scan_cols = list(global_order[:min(m, 32)])

        base_serial = [
            "".join(text[r][j] for j in global_order)
            for r in scan_rows
        ]

        # Select diverse actual rows as competing prefix prototypes.
        anchors = [0]
        while len(anchors) < min(4, len(scan_rows)):
            best = None
            best_distance = -1
            for i, candidate in enumerate(scan_rows):
                if i in anchors:
                    continue
                distance = min(
                    self._lcp(base_serial[i], base_serial[a])
                    for a in anchors
                )
                # Prefer a row with the shortest existing prefix agreement.
                score = -distance
                key = (score, -i)
                if best is None or key > best:
                    best = key
                    best_distance = distance
                    best = key
                    chosen = i
            if best is None:
                break
            anchors.append(chosen)

        anchor_rows = [scan_rows[i] for i in anchors]
        anchor_serials = [
            "".join(text[r][j] for j in global_order)
            for r in anchor_rows
        ]

        lookup = {c: j for j, c in enumerate(columns)}
        fallback = self._merge(
            columns, [columns[j] for j in global_order], col_merge
        )
        fallback = [lookup[c] for c in fallback]

        def make_order(row, prototype):
            """Greedily align one row's fields to a prototype suffix."""
            remaining = set(scan_cols)
            order = []
            position = 0

            while remaining:
                best_j = None
                best_match = -1
                for j in remaining:
                    match = self._lcp(text[row][j], prototype[position:])
                    if match > best_match or (
                        match == best_match and (best_j is None or j < best_j)
                    ):
                        best_match = match
                        best_j = j
                order.append(best_j)
                position += len(text[row][best_j])
                remaining.remove(best_j)

            # Complete the permutation with the deterministic global tail.
            used = set(order)
            order.extend(j for j in global_order if j not in used)

            names = self._merge(
                columns, [columns[j] for j in order], col_merge
            )
            return [lookup[c] for c in names]

        orders = [fallback[:] for _ in range(n)]

        for _round in range(2):
            serials = self._strings(text, orders)
            assignments = []

            for r in range(n):
                best_anchor = 0
                best_match = -1
                for a, prototype in enumerate(anchor_serials):
                    match = self._lcp(serials[r], prototype)
                    if match > best_match:
                        best_match = match
                        best_anchor = a
                assignments.append(best_anchor)

            for r in range(n):
                prototype = anchor_serials[assignments[r]]
                orders[r] = make_order(r, prototype)

            # Refresh prototype strings from the actual constructed anchor rows.
            anchor_serials = [
                "".join(text[r][j] for j in orders[r])
                for r in anchor_rows
            ]

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate global and prototype-aligned candidates and return the best."""
        self.df = df
        self.num_rows, self.num_cols = df.shape
        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[r, j]) for j in range(m)]
            for r in range(n)
        ]

        global_orders, global_order, stats = self._global_candidates(
            text, columns, col_merge
        )

        candidates = []
        for order in global_orders:
            orders = [order[:] for _ in range(n)]
            serials = self._strings(text, orders)
            candidates.append((self._reuse(serials), orders, serials))

        aligned = self._prototype_alignment(
            text, columns, col_merge, global_order
        )
        aligned_serials = self._strings(text, aligned)
        candidates.append((
            self._reuse(aligned_serials),
            aligned,
            aligned_serials,
        ))

        _, best_orders, best_serials = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(n),
            key=lambda r: best_serials[r],
        )

        output = [
            [raw[r, j] for j in best_orders[r]]
            for r in row_order
        ]
        orderings = [
            [columns[j] for j in best_orders[r]]
            for r in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

